from __future__ import annotations

import asyncio
import audioop
import json
import time
import uuid
from typing import Any, Dict, Optional, Text

import structlog
from sanic import (  # type: ignore[attr-defined]
    Blueprint,
    HTTPResponse,
    Request,
    Websocket,
    response,
)

from rasa.core.channels import requires_basic_auth
from rasa.core.channels.channel import RuntimeAgent
from rasa.core.channels.voice_ready.utils import (
    CallParameters,
    validate_username_password_credentials,
)
from rasa.core.channels.voice_stream.audio_bytes import L16_24KHZ, RasaAudioBytes
from rasa.core.channels.voice_stream.call_state import (
    BotIsSpeaking,
    BotStoppedSpeaking,
    Marker,
    MarkerType,
    UserIsSpeaking,
    UserStoppedSpeaking,
    call_state,
)
from rasa.core.channels.voice_stream.tts.tts_engine import TTSEngine
from rasa.core.channels.voice_stream.util import repack_voice_credentials
from rasa.core.channels.voice_stream.voice_channel import (
    ContinueConversationAction,
    MarkerInput,
    MarkerMessageOutput,
    NewAudioAction,
    VoiceChannelAction,
    VoiceInputChannel,
    VoiceOutputChannel,
)

logger = structlog.get_logger()

CHIRP_SAMPLE_RATE = 16000
CHIRP_SAMPLE_WIDTH_BYTES = 2
CHIRP_BOT_UTTERANCE_ID_KEY = "bot_utterance_id"
CHIRP_SPEECH_STARTED = "speech.started"
CHIRP_SPEECH_COMPLETED = "speech.completed"


def _discard_pending_bot_is_speaking_events() -> None:
    """Drop queued ``BotIsSpeaking`` events after CHIRP interrupts playback."""
    pending: list[Any] = []
    while True:
        try:
            message = call_state.internal_queue.get_nowait()
        except asyncio.QueueEmpty:
            break
        if isinstance(message, BotIsSpeaking):
            call_state.internal_queue.task_done()
            continue
        pending.append(message)
    for message in pending:
        # Undo the unfinished-task increment from get_nowait() before re-queuing;
        # the monitor will increment it again when it processes the event.
        call_state.internal_queue.task_done()
        call_state.internal_queue.put_nowait(message)


def make_chirp_event(event_type: str, data: Dict[str, Any]) -> str:
    """Create a CHIRP text event."""
    return json.dumps(
        {
            "type": event_type,
            "id": str(uuid.uuid4()),
            "ts_ms": int(time.time() * 1000),
            "data": data,
        }
    )


def _resample_l16_mono(
    audio_bytes: bytes, input_sample_rate: int, output_sample_rate: int
) -> bytes:
    """Resample signed 16-bit mono PCM between CHIRP and Rasa audio rates."""
    if input_sample_rate == output_sample_rate:
        return audio_bytes

    resampled, _ = audioop.ratecv(
        audio_bytes,
        CHIRP_SAMPLE_WIDTH_BYTES,
        1,
        input_sample_rate,
        output_sample_rate,
        None,
    )
    return resampled


class ChirpOutputChannel(VoiceOutputChannel):
    @classmethod
    def name(cls) -> str:
        return "chirp"

    def __init__(self, *args: Any, **kwargs: Any) -> None:
        super().__init__(*args, **kwargs)
        self.current_utterance_id: Optional[str] = None

    def rasa_audio_bytes_to_channel_bytes(
        self, rasa_audio_bytes: RasaAudioBytes
    ) -> bytes:
        return _resample_l16_mono(
            rasa_audio_bytes.data,
            rasa_audio_bytes.format.sample_rate,
            CHIRP_SAMPLE_RATE,
        )

    def channel_bytes_to_message(self, recipient_id: str, channel_bytes: bytes) -> str:
        raise NotImplementedError("CHIRP sends audio as raw WebSocket binary frames.")

    async def send_audio_bytes(
        self, recipient_id: str, audio_bytes: RasaAudioBytes
    ) -> None:
        await self.voice_websocket.send(
            self.rasa_audio_bytes_to_channel_bytes(audio_bytes)
        )

    def create_marker_message(self, marker_input: MarkerInput) -> MarkerMessageOutput:
        if self.current_utterance_id is None:
            self.current_utterance_id = f"rasa-{uuid.uuid4().hex}"

        utterance_id = self.current_utterance_id
        event_type = (
            CHIRP_SPEECH_STARTED
            if marker_input.marker_type == MarkerType.START
            else CHIRP_SPEECH_COMPLETED
        )

        if marker_input.marker_type == MarkerType.END:
            self.current_utterance_id = None

        if marker_input.marker_type in {MarkerType.START, MarkerType.END}:
            call_state.set_marker(
                Marker(
                    marker_id=utterance_id,
                    marker_type=marker_input.marker_type,
                    step_type=marker_input.step_type,
                )
            )

        return MarkerMessageOutput(
            message_id=utterance_id,
            message=make_chirp_event(
                event_type,
                {"utterance_id": utterance_id},
            ),
        )

    async def send_start_marker(self, marker_input: MarkerInput) -> None:
        self.current_utterance_id = f"rasa-{uuid.uuid4().hex}"
        call_state.channel_data[CHIRP_BOT_UTTERANCE_ID_KEY] = self.current_utterance_id
        # Set synchronously — CHIRP has no marker echo, so async queue updates
        # arrive too late for should_interrupt() during the first user words.
        call_state.is_bot_speaking = True
        if marker_input.step_type is not None:
            call_state.current_bot_utterance_type = marker_input.step_type

        marker = self.create_marker_message(
            MarkerInput(
                recipient_id=marker_input.recipient_id,
                marker_type=MarkerType.START,
                step_type=marker_input.step_type,
            )
        )
        await self._send_marker_message_via_websocket(marker.message_id, marker.message)
        await call_state.enqueue_event(BotIsSpeaking())

    async def send_end_marker(self, marker_input: MarkerInput) -> None:
        # Pop before any await so interrupt_playback cannot claim the same utterance.
        bot_utterance_id = call_state.channel_data.pop(CHIRP_BOT_UTTERANCE_ID_KEY, None)
        if bot_utterance_id is not None:
            marker = self.create_marker_message(marker_input)
            await self._send_marker_message_via_websocket(
                marker.message_id, marker.message
            )
            self.latest_message_id = marker.message_id
        elif self.current_utterance_id is not None:
            self.latest_message_id = self.current_utterance_id
            self.current_utterance_id = None

        call_state.is_bot_speaking = False
        call_state.current_bot_utterance_type = None
        await call_state.enqueue_event(BotStoppedSpeaking())

        if call_state.should_hangup:
            logger.debug("chirp.hangup", utterance_id=self.latest_message_id)
            await self.voice_websocket.close(code=1000, reason="call ended")

    async def send_intermediate_marker(self, marker_input: MarkerInput) -> None:
        """CHIRP has no intermediate speech boundary events."""


class ChirpInputChannel(VoiceInputChannel):
    # CHIRP has no marker echo: it sets `is_bot_speaking` synchronously and never
    # acks/removes playback markers, so silence monitoring must not wait on them.
    tracks_audio_playback = False

    @classmethod
    def name(cls) -> str:
        return "chirp"

    def __init__(
        self,
        server_url: str,
        asr_config: Dict[str, Any],
        tts_config: Dict[str, Any],
        interruptions: Optional[Dict[str, int]] = None,
        silence_timeout: float | int | None = None,
        username: Optional[Text] = None,
        password: Optional[Text] = None,
    ) -> None:
        super().__init__(server_url, asr_config, tts_config, interruptions)
        self.username = username
        self.password = password
        self.audio_format = L16_24KHZ
        self.silence_timeout = silence_timeout
        self.current_utterance_id: Optional[str] = None

    @classmethod
    def from_credentials(
        cls, credentials: Optional[Dict[Text, Any]]
    ) -> ChirpInputChannel:
        cls.validate_credentials(credentials)
        new_creds = repack_voice_credentials(credentials or {})
        return cls(**new_creds)

    @classmethod
    def validate_credentials(cls, credentials: Optional[Dict[Text, Any]]) -> None:
        cls.validate_basic_credentials(credentials)
        username = credentials.get("username")  # type: ignore[union-attr]
        password = credentials.get("password")  # type: ignore[union-attr]
        validate_username_password_credentials(username, password, "CHIRP")

    def channel_bytes_to_rasa_audio_bytes(self, input_bytes: bytes) -> RasaAudioBytes:
        return RasaAudioBytes(
            _resample_l16_mono(
                input_bytes,
                CHIRP_SAMPLE_RATE,
                self.audio_format.sample_rate,
            ),
            format=self.audio_format,
        )

    async def collect_call_parameters(
        self,
        channel_websocket: Websocket,
        request: Optional[Any] = None,
    ) -> Optional[CallParameters]:
        call_id = f"chirp-{uuid.uuid4()}"
        language: Optional[str] = None
        if request is not None:
            language = request.args.get("language") or None

        return CallParameters(
            call_id=call_id,
            user_phone="chirp",
            bot_phone="chirp",
            stream_id=call_id,
            language=language,
        )

    async def _send_session_error(self, ws: Websocket, code: str, message: str) -> None:
        await ws.send(
            make_chirp_event(
                "session.error",
                {
                    "code": code,
                    "message": message,
                },
            )
        )

    async def _map_binary_message(
        self, message: bytes, ws: Websocket
    ) -> VoiceChannelAction:
        if not message or len(message) % CHIRP_SAMPLE_WIDTH_BYTES != 0:
            await self._send_session_error(
                ws,
                "INVALID_AUDIO_FRAME",
                "Audio frames must be non-empty and have an even byte length.",
            )
            return ContinueConversationAction()

        return NewAudioAction(self.channel_bytes_to_rasa_audio_bytes(message))

    async def _map_text_event(self, message: str, ws: Websocket) -> VoiceChannelAction:
        try:
            event = json.loads(message)
        except json.JSONDecodeError:
            await self._send_session_error(
                ws,
                "INVALID_MESSAGE",
                "Text frames must be valid JSON.",
            )
            return ContinueConversationAction()

        event_type = event.get("type")
        data = event.get("data") or {}

        if event_type in {CHIRP_SPEECH_STARTED, CHIRP_SPEECH_COMPLETED}:
            utterance_id = data.get("utterance_id")
            if not utterance_id:
                await self._send_session_error(
                    ws,
                    "MISSING_FIELD",
                    f"{event_type} requires data.utterance_id.",
                )
                return ContinueConversationAction()

            self.current_utterance_id = (
                utterance_id if event_type == CHIRP_SPEECH_STARTED else None
            )
            if event_type == CHIRP_SPEECH_STARTED:
                call_state.is_user_speaking = True
                await call_state.enqueue_event(UserIsSpeaking())
            else:
                call_state.is_user_speaking = False
                await call_state.enqueue_event(UserStoppedSpeaking())
            logger.debug(
                "chirp.speech_event.received",
                event_type=event_type,
                utterance_id=utterance_id,
            )
        elif event_type == "session.error":
            logger.debug("chirp.session_error.received", data=data)
        else:
            await self._send_session_error(
                ws,
                "INVALID_MESSAGE",
                f"Unexpected CHIRP event type: {event_type!r}.",
            )

        return ContinueConversationAction()

    async def map_input_message(
        self, message: Any, ws: Websocket
    ) -> VoiceChannelAction:
        if isinstance(message, bytes):
            return await self._map_binary_message(message, ws)

        return await self._map_text_event(message, ws)

    async def interrupt_playback(
        self, ws: Websocket, call_parameters: CallParameters
    ) -> None:
        """Stop bot playback on Bluejay and signal the Digital Human can speak."""
        bot_utterance_id = call_state.channel_data.pop(CHIRP_BOT_UTTERANCE_ID_KEY, None)
        if bot_utterance_id:
            await ws.send(
                make_chirp_event(
                    CHIRP_SPEECH_COMPLETED,
                    {"utterance_id": bot_utterance_id},
                )
            )

        utterance_id = f"user-{uuid.uuid4().hex}"
        logger.debug(
            "chirp.interrupt_playback",
            utterance_id=utterance_id,
            bot_utterance_id=bot_utterance_id,
        )
        await ws.send(
            make_chirp_event(CHIRP_SPEECH_STARTED, {"utterance_id": utterance_id})
        )
        call_state.is_bot_speaking = False
        call_state.current_bot_utterance_type = None
        # send_start_marker sets is_bot_speaking synchronously and still enqueues
        # BotIsSpeaking; drop stale queue events so the monitor cannot flip the
        # flag back to True after an interrupt.
        _discard_pending_bot_is_speaking_events()
        await call_state.enqueue_event(BotStoppedSpeaking())

    def create_output_channel(
        self, voice_websocket: Websocket, tts_engine: TTSEngine
    ) -> VoiceOutputChannel:
        return ChirpOutputChannel(
            voice_websocket=voice_websocket,
            tts_engine=tts_engine,
            tts_cache=self.tts_cache,
            audio_format=self.audio_format,
        )

    def conversation_blueprint(self, agent: RuntimeAgent) -> Blueprint:
        """Register CHIRP routes; used by ``channel.register()`` at startup."""
        self._runtime_agent = agent
        blueprint = Blueprint("chirp", __name__)

        @blueprint.route("/", methods=["GET"])
        async def health(_: Request) -> HTTPResponse:
            return response.json({"status": "ok"})

        @blueprint.websocket("/websocket")  # type: ignore[misc]
        @requires_basic_auth(self.username, self.password)
        async def handle_message(request: Request, ws: Websocket) -> None:
            try:
                await self.run_audio_streaming(self._runtime_agent, ws, request=request)
            except Exception as e:
                logger.error("chirp.websocket.error", error=str(e))
                await ws.close(code=1011, reason="Error during audio streaming")

        return blueprint
